B.UY=new A.bo(B.aO,["\u0627\u0644\u062a\u062c\u0645\u064a\u0644 \u0648\u0627\u0644\u0644\u064a\u0632\u0631",B.rx,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0641\u0635\u0644\u064a","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0641\u064a \u0639\u0644\u0648\u0645 \u0648\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u062a\u062c\u0645\u064a\u0644 \u0648\u0627\u0644\u0639\u0646\u0627\u064a\u0629 \u0628\u0627\u0644\u0628\u0634\u0631\u0629 \u0648\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0627\u062a \u0627\u0644\u0644\u064a\u0632\u0631 \u0627\u0644\u0637\u0628\u064a.","\u062a\u062e\u0631\u064a\u062c \u0645\u062a\u062e\u0635\u0635\u064a\u0646 \u0645\u0624\u0647\u0644\u064a\u0646 \u0639\u0644\u0645\u064a\u0627\u064b \u0648\u0639\u0645\u0644\u064a\u0627\u064b \u0644\u0644\u0639\u0645\u0644 \u0641\u064a \u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u062a\u062c\u0645\u064a\u0644 \u0627\u0644\u0637\u0628\u064a\u0629 \u0648\u0627\u0644\u0639\u0644\u0627\u062c\u064a\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629.","1. \u0625\u062a\u0642\u0627\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0644\u064a\u0632\u0631 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0644\u0623\u063a\u0631\u0627\u0636 \u0627\u0644\u062a\u062c\u0645\u064a\u0644 \u0648\u0627\u0644\u0639\u0644\u0627\u062c.\n2. \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0635\u062d\u064a\u0629 \u0648\u0627\u0644\u0648\u0642\u0627\u0626\u064a\u0629 \u0641\u064a \u0627\u0644\u0639\u0646\u0627\u064a\u0629 \u0628\u0627\u0644\u0628\u0634\u0631\u0629 \u0648\u0627\u0644\u062c\u0633\u0645.\n3. \u0645\u0648\u0627\u0643\u0628\u0629 \u0627\u0644\u0627\u0628\u062a\u0643\u0627\u0631\u0627\u062a \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0629 \u0641\u064a \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u062c\u0645\u064a\u0644 \u0627\u0644\u0637\u0628\u064a."],t.R)
B.UZ=new A.bo(B.aO,["\u0627\u0644\u0642\u0627\u0646\u0648\u0646",B.mz,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u0646\u0634\u0631 \u0627\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0648\u0625\u0639\u062f\u0627\u062f \u062c\u064a\u0644 \u0648\u0627\u0639\u064d \u0628\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u0634\u0631\u064a\u0639\u0627\u062a \u0648\u0627\u0644\u0646\u0638\u0645 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629.","\u062a\u062e\u0631\u064a\u062c \u0642\u0627\u0646\u0648\u0646\u064a\u064a\u0646 \u064a\u0645\u062a\u0644\u0643\u0648\u0646 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0648\u0627\u0644\u062f\u0641\u0627\u0639 \u0639\u0646 \u0627\u0644\u062d\u0642\u0648\u0642 \u0648\u0625\u0631\u0633\u0627\u0621 \u062f\u0639\u0627\u0626\u0645 \u0627\u0644\u0639\u062f\u0627\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u062c\u062a\u0645\u0639.","1. \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0639\u0645\u064a\u0642 \u0644\u0645\u062e\u062a\u0644\u0641 \u0641\u0631\u0648\u0639 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0639\u0631\u0627\u0642\u064a \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0646.\n2. \u062a\u0639\u0632\u064a\u0632 \u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0639\u0627\u062a.\n3. \u062a\u0631\u0633\u064a\u062e \u0645\u0628\u0627\u062f\u0626 \u0633\u064a\u0627\u062f\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0648\u062d\u0642\u0648\u0642 \u0627\u0644\u0625\u0646\u0633\u0627\u0646."],t.R)
B.V_=new A.bo(B.aO,["\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u062a\u062e\u062f\u064a\u0631",B.rA,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0641\u064a \u0625\u0639\u062f\u0627\u062f \u0643\u0648\u0627\u062f\u0631 \u062a\u062e\u062f\u064a\u0631 \u062a\u0642\u0646\u064a\u0629 \u0630\u0627\u062a \u0643\u0641\u0627\u0621\u0629 \u0639\u0627\u0644\u064a\u0629 \u062a\u0633\u0647\u0645 \u0641\u064a \u0627\u0644\u0627\u0631\u062a\u0642\u0627\u0621 \u0628\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0629 \u0627\u0644\u062c\u0631\u0627\u062d\u064a\u0629.","\u062a\u0623\u0647\u064a\u0644 \u062a\u0642\u0646\u064a\u064a \u062a\u062e\u062f\u064a\u0631 \u0645\u0633\u0644\u062d\u064a\u0646 \u0628\u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0639\u0645\u0644\u064a \u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u062a\u062e\u062f\u064a\u0631 \u0648\u063a\u0631\u0641 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a.","1. \u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0631\u064a\u0636 \u0628\u062f\u0642\u0629 \u0642\u0628\u0644 \u0648\u0623\u062b\u0646\u0627\u0621 \u0648\u0628\u0639\u062f \u0627\u0644\u062a\u062e\u062f\u064a\u0631.\n2. \u0627\u0644\u062a\u0639\u0627\u0645\u0644 \u0627\u0644\u0627\u062d\u062a\u0631\u0627\u0641\u064a \u0645\u0639 \u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0625\u0646\u0639\u0627\u0634 \u0648\u0645\u0639\u062f\u0627\u062a \u0627\u0644\u062a\u0646\u0641\u0633 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a.\n3. \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0627\u0644\u062a\u0627\u0645 \u0628\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u062a\u0639\u0642\u064a\u0645."],t.R)
B.V0=new A.bo(B.aO,["\u0627\u0644\u0635\u064a\u062f\u0644\u0629",B.rC,"\u0635\u0628\u0627\u062d\u064a","5 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0641\u0635\u0644\u064a","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0635\u064a\u062f\u0644\u0627\u0646\u064a \u0648\u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0639\u0644\u0645\u064a \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062f\u0648\u0627\u0626\u064a\u0629 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0639\u0631\u0627\u0642.","\u062a\u062e\u0631\u064a\u062c \u0635\u064a\u0627\u062f\u0644\u0629 \u064a\u0645\u062a\u0644\u0643\u0648\u0646 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0647\u0646\u064a\u0629 \u0644\u0644\u062a\u0639\u0627\u0645\u0644 \u0627\u0644\u0641\u0639\u0627\u0644 \u0645\u0639 \u0627\u0644\u0623\u062f\u0648\u064a\u0629 \u0648\u0627\u0644\u0631\u0639\u0627\u064a\u0629 \u0627\u0644\u0635\u062d\u064a\u0629.","1. \u0641\u0647\u0645 \u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u0645\u0631\u0643\u0628\u0627\u062a \u0627\u0644\u062f\u0648\u0627\u0626\u064a\u0629 \u0648\u062a\u0635\u0646\u064a\u0639\u0647\u0627.\n2. \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u062f\u0648\u0631 \u0627\u0644\u0633\u0631\u064a\u0631\u064a \u0644\u0644\u0635\u064a\u062f\u0644\u0627\u0646\u064a \u0641\u064a \u0627\u0644\u0641\u0631\u064a\u0642 \u0627\u0644\u0635\u062d\u064a.\n3. \u062f\u0639\u0645 \u0627\u0644\u0623\u0628\u062d\u0627\u062b \u0627\u0644\u062f\u0648\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0628\u062a\u0643\u0631\u0629."],t.R)
B.V1=new A.bo(B.aO,["\u062a\u0642\u0646\u064a\u0627\u062a \u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u0623\u0633\u0646\u0627\u0646",B.rU,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0641\u0635\u0644\u064a","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u062a\u0642\u062f\u064a\u0645 \u0628\u0631\u0627\u0645\u062c \u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u062a\u0642\u0646\u064a\u0629 \u0645\u062a\u0637\u0648\u0631\u0629 \u0644\u0625\u0646\u062a\u0627\u062c \u0627\u0644\u062a\u0639\u0648\u064a\u0636\u0627\u062a \u0627\u0644\u0633\u0631\u064a\u0629 \u0648\u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a\u0629 \u0628\u062f\u0642\u0629 \u0639\u0627\u0644\u064a\u0629.","\u0625\u0639\u062f\u0627\u062f \u062a\u0642\u0646\u064a\u064a\u0646 \u0645\u0647\u0631\u0629 \u0642\u0627\u062f\u0631\u064a\u0646 \u0639\u0644\u0649 \u062a\u0635\u0645\u064a\u0645 \u0648\u0635\u0646\u0627\u0639\u0629 \u0645\u062e\u062a\u0644\u0641 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u0639\u0648\u064a\u0636\u0627\u062a \u0648\u0627\u0644\u062c\u0633\u0648\u0631 \u0648\u0627\u0644\u0623\u0637\u0642\u0645 \u0627\u0644\u0633\u0646\u064a\u0629.","1. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0631\u0642\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0641\u064a \u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u0623\u0633\u0646\u0627\u0646.\n2. \u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0627\u0644\u0641\u0639\u0627\u0644 \u0645\u0639 \u0639\u064a\u0627\u062f\u0627\u062a \u0648\u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u0623\u0633\u0646\u0627\u0646.\n3. \u0631\u0641\u0639 \u0627\u0644\u0645\u0647\u0627\u0631\u0629 \u0627\u0644\u064a\u062f\u0648\u064a\u0629 \u0648\u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0644\u0644\u0637\u0644\u0628\u0629."],t.R)
B.V2=new A.bo(B.aO,["\u0627\u0644\u0645\u062d\u0627\u0633\u0628\u0629",B.mx,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u0646\u064a\u0629 \u0641\u064a \u0639\u0644\u0648\u0645 \u0627\u0644\u0645\u062d\u0627\u0633\u0628\u0629 \u0648\u0627\u0644\u062a\u062f\u0642\u064a\u0642 \u0627\u0644\u0645\u0627\u0644\u064a.","\u0625\u0639\u062f\u0627\u062f \u0645\u062d\u0627\u0633\u0628\u064a\u0646 \u0645\u0624\u0647\u0644\u064a\u0646 \u0639\u0644\u0645\u064a\u0627\u064b \u0648\u0639\u0645\u0644\u064a\u0627\u064b \u0644\u0644\u0639\u0645\u0644 \u0641\u064a \u0627\u0644\u0642\u0637\u0627\u0639\u064a\u0646 \u0627\u0644\u0645\u0627\u0644\u064a \u0648\u0627\u0644\u0645\u0635\u0631\u0641\u064a \u0648\u0641\u0642 \u0627\u0644\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0645\u062d\u0627\u0633\u0628\u064a\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629.","1. \u0625\u062a\u0642\u0627\u0646 \u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0648\u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0627\u0644\u064a \u0648\u0627\u0644\u062a\u062f\u0642\u064a\u0642.\n2. \u0645\u0648\u0627\u0643\u0628\u0629 \u0627\u0644\u0646\u0638\u0645 \u0627\u0644\u0645\u062d\u0627\u0633\u0628\u064a\u0629 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629.\n3. \u062a\u0644\u0628\u064a\u0629 \u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0633\u0648\u0642 \u0627\u0644\u0639\u0645\u0644 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0621\u0627\u062a \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u0646\u0632\u064a\u0647\u0629."],t.R)
B.V3=new A.bo(B.aO,["\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629",B.mB,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0633\u0646\u0648\u064a","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u0625\u0639\u062f\u0627\u062f \u062a\u062f\u0631\u064a\u0633\u064a\u064a\u0646 \u0648\u0628\u0627\u062d\u062b\u064a\u0646 \u0643\u0641\u0624\u0629 \u0641\u064a \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0648\u0622\u062f\u0627\u0628\u0647\u0627 \u0648\u0637\u0631\u0642 \u062a\u062f\u0631\u064a\u0633\u0647\u0627.","\u0631\u0641\u062f \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0628\u0643\u0648\u0627\u062f\u0631 \u062a\u062f\u0631\u064a\u0633\u064a\u0629 \u062a\u0645\u062a\u0644\u0643 \u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0644\u063a\u0648\u064a \u0648\u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0627\u0644\u0641\u0639\u0627\u0644 \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629.","1. \u062a\u0637\u0648\u064a\u0631 \u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u0643\u0644\u0627\u0645 \u0648\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0644\u062f\u0649 \u0627\u0644\u0637\u0644\u0628\u0629.\n2. \u0627\u0644\u0625\u062d\u0627\u0637\u0629 \u0628\u0623\u062d\u062f\u062b \u0637\u0631\u0627\u0626\u0642 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0644\u063a\u0648\u064a.\n3. \u062a\u0634\u062c\u064a\u0639 \u0627\u0644\u062f\u0631\u0627\u0633\u0627\u062a \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0648\u0627\u0644\u0623\u062f\u0628\u064a\u0629 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629."],t.R)
B.V4=new A.bo(B.aO,["\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629 \u0648\u0639\u0644\u0648\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u0629",B.rL,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0641\u0635\u0644\u064a","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0641\u064a \u0646\u0634\u0631 \u0627\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0635\u062d\u064a\u0629 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0625\u0639\u062f\u0627\u062f \u0642\u064a\u0627\u062f\u0627\u062a \u0643\u0641\u0624\u0629 \u0641\u064a \u0639\u0644\u0648\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u0629.","\u0625\u0639\u062f\u0627\u062f \u0645\u0639\u0644\u0645\u064a\u0646 \u0648\u0645\u062f\u0631\u0628\u064a\u0646 \u0648\u0628\u0627\u062d\u062b\u064a\u0646 \u0641\u064a \u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629 \u0648\u0639\u0644\u0648\u0645 \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0631\u064a\u0627\u0636\u064a.","1. \u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0644\u064a\u0627\u0642\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u062d\u0631\u0643\u064a\u0629 \u0628\u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629.\n2. \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0623\u0633\u0633 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0631\u064a\u0627\u0636\u064a \u0648\u0627\u0644\u0635\u062d\u064a.\n3. \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0631\u0648\u062d \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062c\u0645\u0627\u0639\u064a."],t.R)
B.V5=new A.bo(B.aO,["\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0646\u0641\u0637",B.rt,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0642\u0633\u0645 \u0645\u0631\u062c\u0639\u0627\u064b \u0627\u0643\u0627\u062f\u064a\u0645\u064a\u0627\u064b \u0648\u0628\u062d\u062b\u064a\u0627\u064b \u0631\u0627\u0626\u062f\u0627\u064b \u0641\u064a \u0642\u0637\u0627\u0639 \u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0648\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u062b\u0631\u0648 \u0627\u0644\u0646\u0641\u0637\u064a\u0629.","\u0625\u0639\u062f\u0627\u062f \u0645\u0647\u0646\u062f\u0633\u064a \u0646\u0641\u0637 \u0623\u064f\u0643\u0641\u0627\u0621 \u0642\u0627\u062f\u0631\u064a\u0646 \u0639\u0644\u0649 \u0625\u062f\u0627\u0631\u0629 \u0648\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0646\u0641\u0637\u064a\u0629 \u0648\u0641\u0642 \u0623\u062d\u062f\u062b \u0627\u0644\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0647\u0646\u062f\u0633\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u0626\u064a\u0629.","1. \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0648\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0627\u0644\u0646\u0641\u0637 \u0648\u0627\u0644\u063a\u0627\u0632 \u0628\u0623\u0641\u0636\u0644 \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a\u0629 \u0648\u0627\u0644\u0622\u0645\u0646\u0629.\n2. \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0623\u062b\u0631 \u0627\u0644\u0628\u064a\u0626\u064a \u0644\u0644\u0635\u0646\u0627\u0639\u0627\u062a \u0627\u0644\u0646\u0641\u0637\u064a\u0629.\n3. \u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0645\u0639 \u0627\u0644\u0634\u0631\u0643\u0627\u062a \u0627\u0644\u0642\u0637\u0627\u0639\u064a\u0629 \u0627\u0644\u0646\u0641\u0637\u064a\u0629."],t.R)
B.V6=new A.bo(B.aO,["\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629",B.rv,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u0645\u062c\u0627\u0644\u0627\u062a \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0642\u062f\u0631\u0629 \u0648\u0627\u0644\u0645\u0646\u0638\u0648\u0645\u0627\u062a \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629.","\u062a\u062e\u0631\u064a\u062c \u062a\u0642\u0646\u064a\u064a\u0646 \u0628\u0645\u0647\u0627\u0631\u0627\u062a \u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0648\u0641\u062d\u0635 \u0648\u062a\u0634\u063a\u064a\u0644 \u0634\u0628\u0643\u0627\u062a \u0648\u0645\u0646\u0638\u0648\u0645\u0627\u062a \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629.","1. \u0625\u062f\u0627\u0631\u0629 \u0648\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0623\u062d\u0645\u0627\u0644 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629 \u0628\u0643\u0641\u0627\u0621\u0629 \u0639\u0627\u0644\u064a\u0629.\n2. \u0635\u064a\u0627\u0646\u0629 \u0648\u062a\u0634\u063a\u064a\u0644 \u0645\u062d\u0637\u0627\u062a \u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u062f.\n3. \u0645\u0648\u0627\u0643\u0628\u0629 \u0627\u0644\u062a\u0637\u0648\u0631\u0627\u062a \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0639\u062f\u0627\u062a \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629."],t.R)
B.V7=new A.bo(B.aO,["\u0647\u0646\u062f\u0633\u0629 \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0637\u0628\u064a\u0629",B.rT,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0642\u0633\u0645 \u062f\u0639\u0627\u0645\u0629 \u0623\u0633\u0627\u0633\u064a\u0629 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u0635\u062d\u064a \u0639\u0628\u0631 \u0647\u0646\u062f\u0633\u0629 \u0648\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0637\u0628\u064a\u0629.","\u0625\u0639\u062f\u0627\u062f \u0645\u0647\u0646\u062f\u0633\u064a\u0646 \u062a\u0642\u0646\u064a\u064a\u0646 \u0642\u0627\u062f\u0631\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u0644\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0648\u0635\u064a\u0627\u0646\u062a\u0647\u0627 \u0648\u062a\u0634\u062e\u064a\u0635 \u0623\u0639\u0637\u0627\u0644\u0647\u0627.","1. \u0633\u062f \u062d\u0627\u062c\u0629 \u0627\u0644\u0645\u0633\u062a\u0634\u0641\u064a\u0627\u062a \u0648\u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0635\u062d\u064a\u0629 \u0644\u0643\u0648\u0627\u062f\u0631 \u0635\u064a\u0627\u0646\u0629 \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0637\u0628\u064a\u0629.\n2. \u0641\u0647\u0645 \u0627\u0644\u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0641\u064a\u0632\u064a\u0627\u0626\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a\u0629 \u0644\u0644\u0627\u062c\u0647\u0632\u0629 \u0627\u0644\u0639\u0644\u0627\u062c\u064a\u0629 \u0648\u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a\u0629.\n3. \u062a\u0639\u0632\u064a\u0632 \u062c\u0648\u062f\u0629 \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0629 \u0628\u0627\u0644\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u0642\u062f\u0645\u0629."],t.R)
B.V8=new A.bo(B.aO,["\u0639\u0644\u0648\u0645 \u0641\u064a\u0632\u064a\u0627\u0621 \u0637\u0628\u064a\u0629",B.rP,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0641\u064a \u062a\u0637\u0628\u064a\u0642 \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0641\u064a\u0632\u064a\u0627\u0621 \u0644\u062e\u062f\u0645\u0629 \u0627\u0644\u0637\u0628 \u0627\u0644\u062d\u062f\u064a\u062b \u0648\u0627\u0644\u062a\u0634\u062e\u064a\u0635 \u0648\u0627\u0644\u0639\u0644\u0627\u062c \u0627\u0644\u0625\u0634\u0639\u0627\u0639\u064a.","\u0625\u0639\u062f\u0627\u062f \u0645\u062a\u062e\u0635\u0635\u064a\u0646 \u0641\u064a \u0627\u0644\u0641\u064a\u0632\u064a\u0627\u0621 \u0627\u0644\u0637\u0628\u064a\u0629 \u0644\u0636\u0645\u0627\u0646 \u0643\u0641\u0627\u0621\u0629 \u0648\u0623\u0645\u0627\u0646 \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0637\u0628\u064a\u0629 \u0627\u0644\u0625\u0634\u0639\u0627\u0639\u064a\u0629 \u0648\u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a\u0629.","1. \u062d\u0633\u0627\u0628 \u062c\u0631\u0639\u0627\u062a \u0627\u0644\u0625\u0634\u0639\u0627\u0639 \u0627\u0644\u0639\u0644\u0627\u062c\u064a \u0628\u062f\u0642\u0629 \u0644\u0644\u0645\u0631\u0636\u0649.\n2. \u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0641\u062d\u0648\u0635\u0627\u062a \u0627\u0644\u0648\u0642\u0627\u0626\u064a\u0629 \u0644\u0636\u0645\u0627\u0646 \u062e\u0644\u0648 \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0645\u0646 \u0627\u0644\u062a\u0633\u0631\u064a\u0628 \u0627\u0644\u0625\u0634\u0639\u0627\u0639\u064a.\n3. \u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0645\u0639 \u0627\u0644\u0637\u0648\u0627\u0642\u0645 \u0627\u0644\u0637\u0628\u064a\u0629 \u0641\u064a \u062a\u0637\u0648\u064a\u0631 \u0628\u0631\u0648\u062a\u0648\u0643\u0648\u0644\u0627\u062a \u0627\u0644\u0639\u0644\u0627\u062c."],t.R)
B.V9=new A.bo(B.aO,["\u0625\u062f\u0627\u0631\u0629 \u0648\u062a\u0633\u0648\u064a\u0642 \u0627\u0644\u0646\u0641\u0637 \u0648\u0627\u0644\u063a\u0627\u0632",B.rO,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u0625\u062f\u0627\u0631\u0629 \u0633\u0644\u0627\u0633\u0644 \u0627\u0644\u0625\u0645\u062f\u0627\u062f \u0648\u0627\u0644\u062a\u0633\u0648\u064a\u0642 \u0641\u064a \u0642\u0637\u0627\u0639 \u0627\u0644\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u0646\u0641\u0637 \u0648\u0627\u0644\u063a\u0627\u0632.","\u062a\u062e\u0631\u064a\u062c \u0643\u0648\u0627\u062f\u0631 \u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u062a\u0633\u0648\u064a\u0642\u064a\u0629 \u0645\u062a\u062e\u0635\u0635\u0629 \u062a\u0641\u0647\u0645 \u0627\u0642\u062a\u0635\u0627\u062f\u064a\u0627\u062a \u0627\u0644\u0646\u0641\u0637 \u0648\u0627\u0644\u063a\u0627\u0632 \u0648\u0622\u0644\u064a\u0627\u062a \u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u0639\u0627\u0644\u0645\u064a.","1. \u062f\u0631\u0627\u0633\u0629 \u0622\u0644\u064a\u0627\u062a \u0627\u0644\u062a\u0633\u0648\u064a\u0642 \u0627\u0644\u0639\u0627\u0644\u0645\u064a \u0644\u0644\u0646\u0641\u0637 \u0648\u0627\u0644\u0645\u0646\u062a\u062c\u0627\u062a \u0627\u0644\u0628\u062a\u0631\u0648\u0643\u064a\u0645\u064a\u0627\u0648\u064a\u0629.\n2. \u062a\u0637\u0628\u064a\u0642 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0641\u064a \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0646\u0641\u0637\u064a\u0629.\n3. \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062c\u062f\u0648\u0649 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a\u0629 \u0644\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0627\u0644\u0637\u0627\u0642\u0648\u064a\u0629."],t.R)
B.Va=new A.bo(B.aO,["\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0623\u0634\u0639\u0629 \u0648\u0627\u0644\u0633\u0648\u0646\u0627\u0631",B.h7,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0641\u0635\u0644\u064a","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u062a\u0642\u062f\u064a\u0645 \u062a\u0639\u0644\u064a\u0645 \u062a\u0642\u0646\u064a \u0645\u062a\u0642\u062f\u0645 \u0641\u064a \u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0637\u0628\u064a \u0627\u0644\u062a\u0635\u0648\u064a\u0631\u064a.","\u0625\u0639\u062f\u0627\u062f \u0645\u0644\u0627\u0643\u0627\u062a \u062a\u0642\u0646\u064a\u0629 \u0645\u062f\u0631\u0628\u0629 \u0639\u0644\u0649 \u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0625\u0634\u0639\u0627\u0639\u064a\u0629 \u0648\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0633\u0648\u0646\u0627\u0631 \u0628\u0623\u0639\u0644\u0649 \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062f\u0642\u0629 \u0648\u0627\u0644\u0623\u0645\u0627\u0646.","1. \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0635\u0648\u0631 \u062a\u0634\u062e\u064a\u0635\u064a\u0629 \u0648\u0627\u0636\u062d\u0629 \u0648\u062f\u0642\u064a\u0642\u0629 \u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0645\u0639\u0627\u0644\u062c.\n2. \u062a\u0637\u0628\u064a\u0642 \u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0648\u0642\u0627\u064a\u0629 \u0645\u0646 \u0627\u0644\u0625\u0634\u0639\u0627\u0639 \u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0645\u0631\u0636\u0649 \u0648\u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646.\n3. \u0645\u0648\u0627\u0643\u0628\u0629 \u0627\u0644\u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0641\u064a \u0627\u0644\u062a\u0635\u0648\u064a\u0631 \u0627\u0644\u0637\u0628\u064a."],t.R)
B.Vb=new A.bo(B.aO,["\u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0645\u062f\u0646\u064a\u0629",B.j0,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0647\u0646\u062f\u0633\u064a \u0627\u0644\u0645\u062f\u0646\u064a \u0648\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0628\u0646\u0649 \u0627\u0644\u062a\u062d\u062a\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u062f\u0627\u0645\u0629.","\u0625\u0639\u062f\u0627\u062f \u0645\u0647\u0646\u062f\u0633\u064a\u0646 \u0645\u062f\u0646\u064a\u064a\u0646 \u064a\u0645\u062a\u0644\u0643\u0648\u0646 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u062e\u0637\u064a\u0637\u060c \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u060c \u0648\u0627\u0644\u0625\u0634\u0631\u0627\u0641 \u0639\u0644\u0649 \u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0627\u0644\u0625\u0646\u0634\u0627\u0626\u064a\u0629 \u0628\u0645\u0639\u0627\u064a\u064a\u0631 \u062c\u0648\u062f\u0629 \u0639\u0627\u0644\u064a\u0629.","1. \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0646\u0634\u0622\u062a \u0627\u0644\u062d\u0636\u0631\u064a\u0629 \u0648\u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u062c\u0633\u0648\u0631 \u0628\u0623\u0645\u0627\u0646 \u0648\u0627\u0633\u062a\u062f\u0627\u0645\u0629.\n2. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u062d\u062f\u062b \u0627\u0644\u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0627\u0644\u0647\u0646\u062f\u0633\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0648\u0627\u0644\u062a\u0646\u0641\u064a\u0630.\n3. \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0623\u062e\u0644\u0627\u0642\u064a\u0627\u062a \u0627\u0644\u0645\u0647\u0646\u0629 \u0648\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0639\u0627\u0645\u0629."],t.R)
B.Vc=new A.bo(B.aO,["\u0647\u0646\u062f\u0633\u0629 \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0623\u0645\u0646 \u0627\u0644\u0633\u064a\u0628\u0631\u0627\u0646\u064a",B.rI,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0628\u064a\u0626\u0629 \u0631\u0642\u0645\u064a\u0629 \u0622\u0645\u0646\u0629 \u0648\u0645\u062d\u0645\u064a\u0629 \u0645\u0646 \u0627\u0644\u062a\u0647\u062f\u064a\u062f\u0627\u062a \u0627\u0644\u0633\u064a\u0628\u0631\u0627\u0646\u064a\u0629 \u0627\u0644\u0645\u062a\u0632\u0627\u064a\u062f\u0629.","\u0625\u0639\u062f\u0627\u062f \u0643\u0648\u0627\u062f\u0631 \u062a\u0642\u0646\u064a\u0629 \u0645\u062a\u062e\u0635\u0635\u0629 \u0644\u062d\u0645\u0627\u064a\u0629 \u0634\u0628\u0643\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0648\u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0631\u0642\u0645\u064a\u0629 \u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u062f\u0648\u0644\u0629 \u0648\u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u062e\u0627\u0635.","1. \u062a\u0623\u0645\u064a\u0646 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0636\u062f \u0627\u0644\u0627\u062e\u062a\u0631\u0627\u0642\u0627\u062a \u0648\u0627\u0644\u0647\u062c\u0645\u0627\u062a \u0627\u0644\u0633\u064a\u0628\u0631\u0627\u0646\u064a\u0629.\n2. \u062a\u0637\u0648\u064a\u0631 \u0623\u062f\u0648\u0627\u062a \u0648\u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0644\u0644\u0643\u0634\u0641 \u0627\u0644\u0645\u0628\u0643\u0631 \u0639\u0646 \u0627\u0644\u062b\u063a\u0631\u0627\u062a \u0627\u0644\u0623\u0645\u0646\u064a\u0629.\n3. \u0646\u0634\u0631 \u0627\u0644\u0648\u0639\u064a \u0628\u0623\u0645\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0631\u0642\u0645\u064a\u0629."],t.R)
B.Vd=new A.bo(B.aO,["\u0639\u0644\u0648\u0645 \u062a\u062d\u0644\u064a\u0644\u0627\u062a \u0645\u0631\u0636\u064a\u0629",B.h7,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u062e\u0628\u0631\u064a \u0648\u0627\u0644\u0628\u062d\u0648\u062b \u0627\u0644\u0637\u0628\u064a\u0629 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u064a\u0629.","\u062a\u062e\u0631\u064a\u062c \u0628\u0627\u062d\u062b\u064a\u0646 \u0648\u0645\u062d\u0644\u0644\u064a\u0646 \u0645\u062e\u062a\u0628\u0631\u064a\u064a\u0646 \u0630\u0648\u064a \u0643\u0641\u0627\u0621\u0629 \u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0641\u062d\u0648\u0635\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0629 \u0627\u0644\u062f\u0642\u064a\u0642\u0629.","1. \u062f\u0642\u0629 \u0648\u0633\u0631\u0639\u0629 \u0641\u064a \u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0641\u062d\u0648\u0635\u0627\u062a \u0627\u0644\u0645\u062e\u062a\u0628\u0631\u064a\u0629 \u0627\u0644\u0633\u0631\u064a\u0631\u064a\u0629.\n2. \u0627\u0644\u062a\u0639\u0627\u0645\u0644 \u0627\u0644\u0622\u0645\u0646 \u0645\u0639 \u0627\u0644\u0639\u064a\u0646\u0627\u062a \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a\u0629 \u0648\u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0645\u062e\u0628\u0631\u064a\u0629 \u0627\u0644\u0645\u062a\u0642\u062f\u0645\u0629.\n3. \u062f\u0639\u0645 \u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0639\u0644\u0645\u064a \u0641\u064a \u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0648\u0627\u0644\u0623\u0648\u0628\u0626\u0629."],t.R)
B.Ve=new A.bo(B.aO,["\u0647\u0646\u062f\u0633\u0629 \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u0648\u0642\u0648\u062f \u0648\u0627\u0644\u0637\u0627\u0642\u0629",B.ry,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0641\u064a \u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a\u0629 \u0648\u0627\u0644\u0645\u062a\u062c\u062f\u062f\u0629 \u0648\u062a\u0637\u0648\u064a\u0631 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0648\u0642\u0648\u062f \u0627\u0644\u062d\u062f\u064a\u062b\u0629.","\u062a\u0623\u0647\u064a\u0644 \u0643\u0648\u0627\u062f\u0631 \u0647\u0646\u062f\u0633\u064a\u0629 \u062a\u0642\u0646\u064a\u0629 \u0642\u0627\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 \u062a\u0642\u0646\u064a\u0627\u062a \u0625\u0646\u062a\u0627\u062c \u0648\u0627\u0633\u062a\u062f\u0627\u0645\u0629 \u0627\u0644\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u0648\u0642\u0648\u062f.","1. \u062f\u0631\u0627\u0633\u0629 \u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0628\u062f\u064a\u0644\u0629 \u0648\u0627\u0644\u0646\u0638\u064a\u0641\u0629.\n2. \u062a\u062d\u0633\u064a\u0646 \u0643\u0641\u0627\u0621\u0629 \u0627\u0633\u062a\u0647\u0644\u0627\u0643 \u0627\u0644\u0648\u0642\u0648\u062f \u0648\u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0627\u0646\u0628\u0639\u0627\u062b\u0627\u062a \u0627\u0644\u0636\u0627\u0631\u0629.\n3. \u062f\u0639\u0645 \u0627\u0644\u062a\u062d\u0648\u0644 \u0646\u062d\u0648 \u0637\u0627\u0642\u0629 \u0645\u0633\u062a\u062f\u0627\u0645\u0629 \u0622\u0645\u0646\u0629."],t.R)
B.Vf=new A.bo(B.aO,["\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a",B.rG,"\u0635\u0628\u0627\u062d\u064a / \u0645\u0633\u0627\u0626\u064a","4 \u0633\u0646\u0648\u0627\u062a","\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633","\u0645\u0633\u0627\u0631 \u0628\u0648\u0644\u0648\u0646\u064a\u0627","null","4 \u062f\u0641\u0639\u0627\u062a","\u0628\u0646\u0627\u0621 \u0642\u0627\u0639\u062f\u0629 \u0631\u0635\u064a\u0646\u0629 \u0641\u064a \u0639\u0644\u0648\u0645 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0648\u062a\u0637\u0628\u064a\u0642\u0627\u062a\u0647 \u0627\u0644\u0630\u0643\u064a\u0629 \u0645\u062d\u0644\u064a\u0627\u064b \u0648\u0639\u0627\u0644\u0645\u064a\u0627\u064b.","\u0631\u0641\u062f \u0633\u0648\u0642 \u0627\u0644\u0639\u0645\u0644 \u0628\u0645\u0647\u0646\u062f\u0633\u064a\u0646 \u0645\u062a\u062e\u0635\u0635\u064a\u0646 \u0641\u064a \u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0622\u0644\u064a \u0648\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0630\u0643\u064a\u0629 \u0644\u062a\u0637\u0648\u064a\u0631 \u062d\u0644\u0648\u0644 \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644.","1. \u062a\u0635\u0645\u064a\u0645 \u0646\u0638\u0645 \u0630\u0643\u064a\u0629 \u062a\u062d\u0627\u0643\u064a \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0628\u0634\u0631\u064a \u0644\u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0627\u0644\u0645\u0639\u0642\u062f\u0629.\n2. \u0625\u062c\u0631\u0627\u0621 \u0628\u062d\u0648\u062b \u0645\u062a\u0642\u062f\u0645\u0629 \u0641\u064a \u0645\u062c\u0627\u0644 \u0627\u0644\u0631\u0648\u0628\u0648\u062a\u0627\u062a \u0648\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a.\n3. \u0646\u0634\u0631 \u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0627\u0628\u062a\u0643\u0627\u0631 \u0627\u0644\u0631\u0642\u0645\u064a."],t.R)
